package com.bank.treasury.service;

import java.util.Arrays;
import java.util.logging.Logger;

// Finds the triplet sum closest to a target obligation.
public class ClosestTripletFinder {
    private static final Logger log = Logger.getLogger(ClosestTripletFinder.class.getName());

    public int closestTripletSum(int[] amounts, int target) {
        if (amounts == null || amounts.length < 3) {
            throw new IllegalArgumentException("Need at least three amounts.");
        }
        Arrays.sort(amounts);
        int closest = amounts[0] + amounts[1] + amounts[2];

        for (int i = 0; i < amounts.length - 2; i++) {
            int left = i + 1;
            int right = amounts.length - 1;
            while (left < right) {
                int sum = amounts[i] + amounts[left] + amounts[right];
                if (Math.abs(sum - target) < Math.abs(closest - target)) {
                    closest = sum; // strictly closer, update best
                }
                if (sum == target) {
                    log.info(() -> "Exact match to target " + target);
                    return sum; // cannot do better than zero distance
                } else if (sum < target) {
                    left++;   // increase the sum
                } else {
                    right--;  // decrease the sum
                }
            }
        }
        final int best = closest;
        log.info(() -> "Closest triplet sum to " + target + " is " + best);
        return closest;
    }
}
