package com.bank.treasury;

import com.bank.treasury.service.ClosestTripletFinder;
import java.util.logging.Logger;

public class ClosestTripletDemo {
    private static final Logger log = Logger.getLogger(ClosestTripletDemo.class.getName());

    public static void main(String[] args) {
        // Pending settlement amounts (in thousands) and a target obligation.
        int[] amounts = {-1, 2, 1, -4};
        int target = 1;

        ClosestTripletFinder finder = new ClosestTripletFinder();
        int best = finder.closestTripletSum(amounts, target);

        log.info(() -> "Target was " + target + ", best achievable total = " + best);
    }
}
